-- 只读验证：检查新增表/索引，不能以此代替数据与权限验收。
SELECT table_name,engine,table_collation FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('ai_hr_position_sequence','ai_hr_position','ai_hr_position_draft','ai_hr_config_version','ai_hr_candidate','ai_hr_fact_snapshot','ai_hr_semantic_snapshot','ai_hr_matching_run','ai_hr_matching_result','ai_hr_policy_version','ai_hr_batch','ai_hr_batch_item') ORDER BY table_name;
SELECT table_name,index_name,non_unique,GROUP_CONCAT(column_name ORDER BY seq_in_index) AS indexed_columns FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name IN ('ai_hr_position_sequence','ai_hr_position','ai_hr_position_draft','ai_hr_config_version','ai_hr_candidate','ai_hr_fact_snapshot','ai_hr_semantic_snapshot','ai_hr_matching_run','ai_hr_matching_result','ai_hr_policy_version','ai_hr_batch','ai_hr_batch_item') GROUP BY table_name,index_name,non_unique ORDER BY table_name,index_name;
